125	/// Parses a query feature that starts with a feature value.
126	///
127	/// This covers reverse ranges such as `(500px <= width)` and interval ranges
128	/// such as `(500px <= width <= 1000px)`.
129	#[inline]
130	fn parse_value_prefixed_query_feature(p: &mut CssParser) -> ParsedSyntax {
131	    if !is_at_value_prefixed_query_feature(p) {
132	        return Absent;
133	    }
134	
135	    let m = p.start();
136	
137	    // Guarded by `is_at_value_prefixed_query_feature` above.
138	    parse_any_query_feature_value(p).ok();
139	    parse_query_feature_range_comparison(p)
140	        .or_add_diagnostic(p, expected_query_feature_range_comparison);
141	    parse_query_feature_name(p).or_add_diagnostic(p, expected_identifier);
142	
143	    if is_at_query_feature_range_comparison(p) {
144	        // Checked by `is_at_query_feature_range_comparison` above.
145	        parse_query_feature_range_comparison(p).ok();
146	        parse_any_query_feature_value(p).or_add_diagnostic(p, expected_query_feature_value);
147	
148	        Present(m.complete(p, CSS_QUERY_FEATURE_RANGE_INTERVAL))
149	    } else {
150	        Present(m.complete(p, CSS_QUERY_FEATURE_REVERSE_RANGE))
151	    }
152	}
153	
154	#[inline]
155	fn is_at_query_feature_range_comparison(p: &mut CssParser) -> bool {
156	    p.at_ts(QUERY_FEATURE_RANGE_COMPARISON_OPERATOR_SET)
157	}
