159	#[inline]
160	fn parse_query_feature_range_comparison(p: &mut CssParser) -> ParsedSyntax {
161	    if !is_at_query_feature_range_comparison(p) {
162	        return Absent;
163	    }
164	
165	    let m = p.start();
166	
167	    p.bump_ts(QUERY_FEATURE_RANGE_COMPARISON_OPERATOR_SET);
168	
169	    Present(m.complete(p, CSS_QUERY_FEATURE_RANGE_COMPARISON))
170	}
171	
172	const QUERY_FEATURE_RANGE_COMPARISON_OPERATOR_SET: TokenSet<CssSyntaxKind> =
173	    token_set![T![>], T![<], T![>=], T![<=], T![=]];
