180	#[inline]
181	fn parse_any_query_feature_value(p: &mut CssParser) -> ParsedSyntax {
182	    if is_at_scss_interpolated_query_feature_value(p) {
183	        parse_scss_interpolated_identifier(p)
184	    } else if is_at_scss_interpolation(p) {
185	        parse_scss_regular_interpolation(p)
186	    } else {
187	        // The concrete query-feature value grammar is narrower than `AnyCssValue`,
188	        // but this shared value parser gives us the right recovery for the current
189	        // media/container feature branches.
190	        parse_any_value(p)
191	    }
192	}
